insert into public.company_interview_packs (slug, name, about, questions)
values
  ('bkash', 'bKash', 'Mobile financial services, and the largest employer of junior engineers in Dhaka. Interviews lean heavily on fundamentals and on whether you can reason about money moving between accounts.', '[{"question": "Why does a payment system care so much about idempotency?", "category": "company"}, {"question": "A transfer is debited but not credited. What do you do first?", "category": "company"}, {"question": "How would you explain bKash to somebody who has never used a bank?", "category": "company"}, {"question": "What would worry you about handling other people''s money?", "category": "company"}]'::jsonb),
  ('grameenphone', 'Grameenphone', 'The largest mobile operator. A long, structured process with an aptitude test before anybody technical sees you.', '[{"question": "Why telecom, and why Grameenphone?", "category": "company"}, {"question": "Tell me about a time you worked with somebody difficult.", "category": "company"}, {"question": "How would you explain a technical problem to a non-technical manager?", "category": "company"}, {"question": "Where do you think mobile data in Bangladesh goes in the next five years?", "category": "company"}]'::jsonb),
  ('pathao', 'Pathao', 'Ride-hailing, delivery and courier. Interviews are practical and fast, and they care whether you have actually built things.', '[{"question": "Show me something you built. Why did you build it that way?", "category": "company"}, {"question": "How would you design the screen a rider sees while waiting for a trip?", "category": "company"}, {"question": "A driver and a customer disagree about a fare. What does the system do?", "category": "company"}, {"question": "What would you measure to know whether a delivery is going badly?", "category": "company"}]'::jsonb),
  ('brac', 'BRAC', 'The largest NGO in the world, and a serious technology employer. Expect questions about impact alongside the technical ones.', '[{"question": "Why development work rather than a private company?", "category": "company"}, {"question": "How would you collect data from field workers with no reliable internet?", "category": "company"}, {"question": "Tell me about a time you had to work with very little.", "category": "company"}, {"question": "How do you know whether a programme is actually helping anyone?", "category": "company"}]'::jsonb),
  ('robi', 'Robi Axiata', 'A mobile operator with a large graduate intake. Structured, competency-based interviews.', '[{"question": "Tell me about a time you led something without being in charge.", "category": "company"}, {"question": "How do you handle being given a target you think is unrealistic?", "category": "company"}, {"question": "What do you do in the first week of a job where nobody explains anything?", "category": "company"}, {"question": "Describe a decision you made with incomplete information.", "category": "company"}]'::jsonb),
  ('shohoz', 'Shohoz', 'Tickets, rides and logistics. A smaller team, so interviews test breadth and whether you can work without much direction.', '[{"question": "You are the only person on a feature. How do you decide what to build first?", "category": "company"}, {"question": "How would you handle a launch during Eid traffic?", "category": "company"}, {"question": "What do you do when the requirements change halfway through?", "category": "company"}, {"question": "Tell me about something you shipped that nobody asked you to.", "category": "company"}]'::jsonb)
