-- Generated by supabase/seed/interview_bank.py. Do not edit by hand.
--
-- interview_question_bank is a cache: the first student to ask for a
-- (role, type, difficulty) pays one of three daily AI actions, and
-- everybody after them gets it free. It has been empty since it was
-- created in 0008, so every student has been paying for questions the
-- last one already generated.
--
-- Seeding it makes interview practice cost nothing from today. The
-- questions are hand-written so they are reviewable in git, do not
-- drift when a model changes, and can be specific to the market these
-- students are actually interviewing in.

-- 90 sets: 10 roles x 3 session types x 3 difficulties.

on conflict (role_slug, session_type, difficulty) do update
  set questions = excluded.questions;

-- ------------------------------------------------------ company packs
--
-- What a student actually wants the night before: not 'behavioural,
-- medium' but 'I have an interview at bKash on Thursday'. Public
-- reference data like career_paths, readable by any signed-in student.

create table if not exists public.company_interview_packs (
  slug       text primary key,
  name       text not null,
  about      text not null,
  questions  jsonb not null,
  created_at timestamptz not null default now()
);

alter table public.company_interview_packs enable row level security;
alter table public.company_interview_packs force row level security;

drop policy if exists company_interview_packs_read on public.company_interview_packs;
create policy company_interview_packs_read on public.company_interview_packs
  for select to authenticated using (true);

comment on table public.company_interview_packs is
  'Employers Bangladeshi students actually apply to, and what each is known '
  'to ask. Reference data, seeded, not user-generated.';

on conflict (slug) do update set
  name = excluded.name, about = excluded.about,
  questions = excluded.questions;

-- ------------------------------------------------------------------- checked
do $$
declare
  v_sets int;
  v_thin int;
begin
  select count(*) into v_sets from public.interview_question_bank;
  if v_sets < 90 then
    raise exception 'expected 90 seeded sets, found %', v_sets;
  end if;

  -- The endpoint slices to the requested count, which defaults to five. A set
  -- with fewer would silently hand a student a shorter interview.
  select count(*) into v_thin from public.interview_question_bank
   where jsonb_array_length(questions) < 5;
  if v_thin > 0 then
    raise exception '% seeded sets have fewer than five questions', v_thin;
  end if;

  if (select count(*) from public.company_interview_packs) < 6 then
    raise exception 'the company packs did not seed';
  end if;
end $$;
